// n8n Code node (JavaScript) — paste this whole block.
// Expects incoming JSON like:
// { "barcode":"101384", "sleep_hours": null, "trouble_sleeping":"No", "waking_up_condition":"Yes", ...optional fields... }
//
// Optional inputs if available (recommended):
// - sleep_mean, sleep_sd  (from your daily snapshot table)
// - chronological_age, biological_sex (or sex)

const COEFS = {
  Intercept: 17.7295,
  SleepScore_z: -0.3332,
  ActivityScore: -0.2574,
  DietScore: 0.0554,
  DiseaseScore: 0.3657,
  StressScore: -0.1376,
  MentalScore: 0.0625,
  chronological_age: -0.3771,
  sex_male: 0.1432,
  sex_pnta: -5.3718,
};

function toNum(v) {
  if (v === null || v === undefined) return null;
  if (typeof v === "number" && Number.isFinite(v)) return v;
  const s = String(v).trim();
  if (!s) return null;
  const n = Number(s);
  return Number.isFinite(n) ? n : null;
}

function ynToBool(v) {
  const s = String(v ?? "").trim().toLowerCase();
  if (["yes", "y", "true", "1"].includes(s)) return true;
  if (["no", "n", "false", "0"].includes(s)) return false;
  return null; // unknown
}

function computeSleepScore(input) {
  const sleepHours = toNum(input.sleep_hours);

  // 1) Duration points (0–10)
  // Neutral default if unknown (sleep_hours null)
  let durationPoints = 5;

  if (sleepHours !== null) {
    if (sleepHours >= 7 && sleepHours <= 8) durationPoints = 10;
    else if (sleepHours >= 6 && sleepHours < 7) durationPoints = 6;
    else if (sleepHours > 8 && sleepHours <= 9) durationPoints = 6;
    else durationPoints = 2;
  }

  // 2) Problems points (0–10)
  // Start at 10, subtract penalties if problems are present.
  let problemsPoints = 10;

  const trouble = ynToBool(input.trouble_sleeping);
  const waking = ynToBool(input.waking_up_condition);

  // If unknown, don't penalize.
  if (trouble === true) problemsPoints -= 4;

  // Your input uses "Yes" / "No" for waking_up_condition.
  // If "Yes" means "waking up feeling bad", penalize.
  if (waking === true) problemsPoints -= 3;

  problemsPoints = Math.max(0, Math.min(10, problemsPoints));

  // 3) Weighted SleepScore (0–100)
  const WEIGHT_DURATION = 0.4;
  const WEIGHT_PROBLEMS = 0.6;

  const raw = durationPoints * WEIGHT_DURATION + problemsPoints * WEIGHT_PROBLEMS;
  const SleepScore = Math.max(0, Math.min(100, Math.round(raw * 10)));

  return { SleepScore, durationPoints, problemsPoints, sleepHours };
}

function zScore(value, mean, sd) {
  if (!Number.isFinite(value)) return 0;
  if (!Number.isFinite(mean)) mean = 60;
  if (!Number.isFinite(sd) || sd === 0) sd = 15;
  return (value - mean) / sd;
}

function predictDeltaBioAge({
  SleepScore_z,
  ActivityScore = 0,
  DietScore = 0,
  DiseaseScore = 0,
  StressScore = 0,
  MentalScore = 0,
  chronological_age,
  sex = "female",
}) {
  const s = String(sex ?? "female").toLowerCase();
  const sex_male = s === "male" ? 1 : 0;
  const sex_pnta = s.includes("prefer") ? 1 : 0;

  const age = Number.isFinite(chronological_age) ? chronological_age : 0;

  const yhat =
    COEFS.Intercept +
    COEFS.SleepScore_z * SleepScore_z +
    COEFS.ActivityScore * ActivityScore +
    COEFS.DietScore * DietScore +
    COEFS.DiseaseScore * DiseaseScore +
    COEFS.StressScore * StressScore +
    COEFS.MentalScore * MentalScore +
    COEFS.chronological_age * age +
    COEFS.sex_male * sex_male +
    COEFS.sex_pnta * sex_pnta;

  return Math.round(yhat * 100) / 100;
}

// --------- n8n entrypoint ---------
const input = ($json && typeof $json === "object") ? $json : {};

// Barcode (keep as string)
const barcode = String(input.barcode ?? "").trim();

// Compute SleepScore
const sleep = computeSleepScore(input);

// Pull mean/sd from snapshot if present; else defaults used
const sleep_mean = toNum(input.sleep_mean);
const sleep_sd = toNum(input.sleep_sd);

// Compute z
const SleepScore_z = zScore(sleep.SleepScore, sleep_mean, sleep_sd);

// Optional: If you have these fields from your pipeline/snapshot, pass them; else default 0
const ActivityScore = toNum(input.ActivityScore) ?? 0;
const DietScore = toNum(input.DietScore) ?? 0;
const DiseaseScore = toNum(input.DiseaseScore) ?? 0;
const StressScore = toNum(input.StressScore) ?? 0;
const MentalScore = toNum(input.MentalScore) ?? 0;

// Chronological age + sex (use whichever field you have)
const chronological_age = toNum(input.chronological_age);
const sex = String(input.biological_sex ?? input.sex ?? "female");

// Predict delta bioage (in years)
const deltaBioAge_pred = predictDeltaBioAge({
  SleepScore_z,
  ActivityScore,
  DietScore,
  DiseaseScore,
  StressScore,
  MentalScore,
  chronological_age: chronological_age ?? 0,
  sex,
});

// If you want just the "BioAge_sleep_effect" term like earlier (coef * z):
const BioAge_sleep_effect = Math.round((COEFS.SleepScore_z * SleepScore_z) * 1000) / 1000;

return [
  {
    json: {
      ok: Boolean(barcode),
      barcode,
      sleep_hours: sleep.sleepHours, // null if missing
      durationPoints: sleep.durationPoints,
      problemsPoints: sleep.problemsPoints,
      SleepScore: sleep.SleepScore,
      SleepScore_z: Math.round(SleepScore_z * 1000) / 1000,
      BioAge_sleep_effect,           // sleep-only contribution
      deltaBioAge_pred,              // full model prediction (years)
    },
  },
];
